this.messageId = document.createElement("span");
this.messageId.classList.add("text-link");
this.messageId.tabIndex = 0;
this.appendChild(this.messageId);

this.messageId.addEventListener("contextmenu", event => {
  gMessageHeader.openMessageIdPopup(event, this);
});
this.messageId.addEventListener("click", event => {
  gMessageHeader.onMessageIdClick(event);
});
this.messageId.addEventListener("keypress", event => {
  if (event.key == "Enter") {
    gMessageHeader.onMessageIdClick(event);
  }

if (!event.screenX) {
  popup.openPopup(event.target, "after_start", 0, 0, true);
  return;
}

// This block sends menu information to WebExtensions.
const messageId = element.id;
const subject = {
  menu: popup,
  tab: popup.documentGlobal,
  onHeaderPaneLink: true,
  linkText: messageId,
  linkUrl: `mid:${messageId.substring(1, messageId.length - 1)}`,
  pageUrl: getMessagePaneBrowser().contentDocument?.URL,
};
subject.wrappedJSObject = subject;
Services.obs.notifyObservers(subject, "on-build-contextmenu");

popup.openPopupAtScreen(event.screenX, event.screenY, true);

const showEventPromise = checkShownEvent(
  extension,
  expectedShowData,
  expectedTab
);
await openMenuPopup(menu, element, { type: "contextmenu" });
const menuItem = menu.querySelector(
  `#menus_mochi_test-menuitem-_${expectedContext}`
);
await showEventPromise;

Assert.ok(menuItem);

const clickEventPromise = checkClickedEvent(
  extension,
  expectedClickData,
  expectedTab
);
await clickItemInMenuPopup(menuItem);
await clickEventPromise;
